func scanManifestFile(root string, coord gitops.Coordinate, file string, stderr io.Writer) []SecretRef {
	data, err := os.ReadFile(file)
	if err != nil {
		fmt.Fprintf(stderr, "warning: read %s: %v\n", repoRel(root, file), err)
		return nil
	}
	var out []SecretRef
	for _, doc := range splitYAMLDocuments(string(data)) {
		var id struct {
			Kind     string `yaml:"kind"`
			Metadata struct {
				Name string `yaml:"name"`
			} `yaml:"metadata"`
		}
		if err := yaml.Unmarshal([]byte(doc), &id); err != nil {
			fmt.Fprintf(stderr, "warning: skipping a malformed document in %s: %v\n", repoRel(root, file), err)
			continue
		}
		if !secretKinds[id.Kind] || id.Metadata.Name == "" {
			continue
		}
		out = append(out, SecretRef{
			Kind:      id.Kind,
			Name:      id.Metadata.Name,
			Component: coord.String(),
			File:      repoRel(root, file),
		})
	}
	return out
}
```

Note: use yaml.Unmarshal without KnownFields — unknown fields ignored (plan requires).

splitYAMLDocuments: split on lines that are exactly "---" possibly with trailing whitespace or "--- ..." content. YAML document separator: line starting with "---" at column 0 (optionally followed by space and content — a directives end marker can have trailing content in doc start). Keep simple: strings.HasPrefix(line, "---") when at line start. To be careful, treat a line equal to "---" or starting "--- " as separator.

```go
func splitYAMLDocuments(data string) []string {
	var docs []string
	var cur strings.Builder
	flush := func() {
		if strings.TrimSpace(cur.String()) != "" {
			docs = append(docs, cur.String())
		}
		cur.Reset()
	}
	for line := range strings.Lines(data) {
		if strings.HasPrefix(line, "---") && (len(line) == 3 || line[3] == ' ' || line[3] == '\t' || line[3] == '\n' || line[3] == '\r') {
			flush()
			continue
		}
		cur.WriteString(line)
	}
	flush()
	return docs
}
```

strings.Lines exists in Go 1.24. Check go version in go.mod. status.go uses strings.SplitSeq (Go 1.24), so fine.

