// ShowResult is the machine-readable outcome of a show: what the GitOps
// repository declares, as one document. Field names are stable and
// additive-only.
type ShowResult struct {
	Repository   RepositoryInfo    `json:"repository"`
	Registry     string            `json:"registry"`
	Argocd       ArgocdInfo        `json:"argocd"`
	Platform     PlatformInfo      `json:"platform"`
	Environments []EnvironmentInfo `json:"environments"` // promotion order
	Systems      []SystemInfo      `json:"systems"`
}

// RepositoryInfo locates the GitOps repository the result was read from.
type RepositoryInfo struct {
	URL string `json:"url"`

	// Revision is the checkout's HEAD — the full sha, because a consumer
	// hands it to git. Plain output shortens it.
	Revision string `json:"revision"`
}

// ArgocdInfo locates the ArgoCD instance the repository reconciles through.
type ArgocdInfo struct {
	Server       string `json:"server"`
	AppNamespace string `json:"appNamespace"`
}

// PlatformInfo carries deploy.yaml's platform declaration. The values are
// deliberately unvalidated in the repository contract and any of the three
// may be empty, so every field is omitempty: absent means "not declared",
// which a consumer must be able to tell apart from an empty string.
type PlatformInfo struct {
	Provider    string `json:"provider,omitempty"`
	Pubsub      string `json:"pubsub,omitempty"`
	SecretStore string `json:"secretStore,omitempty"`
}

// EnvironmentInfo is one environment's declared policy, in promotion order.
type EnvironmentInfo struct {
	Name         string   `json:"name"`
	Sync         string   `json:"sync"` // "auto" | "manual"
	PromotesFrom []string `json:"promotesFrom,omitempty"`

	RequireSourceHealthy bool `json:"requireSourceHealthy,omitempty"`

	// Scratch is carried verbatim from deploy.yaml, where its own doc says
	// the semantics are not yet defined. Reported here because it is declared;
	// the plain table gives it no presence for the same reason.
	Scratch bool `json:"scratch,omitempty"`
}

// SystemInfo is one system's components, grouped under their domain.
type SystemInfo struct {
	Domain     string          `json:"domain"`
	System     string          `json:"system"`
	Components []ComponentInfo `json:"components"`
}

// ComponentInfo is what one component declares, or why it could not be read.
type ComponentInfo struct {
	Name string `json:"name"`

	// Kind is the component's declared kind with the default made explicit:
	// "service" | "shared".
	Kind   string   `json:"kind"`
	Images []string `json:"images,omitempty"`

	// Environments is the component.yaml declared list verbatim, NOT reordered
	// into promotion order: show describes declarations, and reordering would
	// hide what the file actually says.
	Environments []string `json:"environments"`

	// Secrets are the secret-bearing resources found in the component's
	// manifests — shared components in practice, but a service declaring one
	// is worth surfacing too.
	Secrets []SecretRef `json:"secrets,omitempty"`

	// Error reports an unreadable or invalid component.yaml. It never fails
	// the listing: a broken component is a fact worth seeing, not a reason to
	// withhold the rest of the repository.
	Error string `json:"error,omitempty"`
}

// SecretRef names one secret-bearing resource and where it was seen.
type SecretRef struct {
	// Kind is Secret, ExternalSecret, SealedSecret, or secretGenerator for a
	// kustomize-generated secret.
	Kind string `json:"kind"`
	Name string `json:"name"`

	// Component is the owning coordinate ("domain/system/component"). It is
	// redundant with the nesting but lets a consumer render a flat secrets
	// list without walking the systems tree.
	Component string `json:"component"`

	// File is the repository-relative file the resource was seen in. Empty
	// for a secretGenerator, which is declared inside a kustomization.yaml
	// rather than as a resource document.
	File string `json:"file,omitempty"`
}

