	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState

	// gitopsMu guards the cached repository declaration. It is one slot, not
	// keyed by path: there is one GitOps repository per dashboard, and reading
	// it refreshes the same shared checkout the deploy provider locks.
	gitopsMu      sync.Mutex
	gitopsLoaded  bool
	gitopsWarming bool
	gitops        gitopsState
}

mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
// Unlike the deploy endpoints, these carry the verb as a /refresh segment:
// there is no {path...} wildcard forcing the verb last, so the segment form
// is available and reads better. GET serves what has already been read,
// POST runs the command again.
mux.HandleFunc("GET /api/gitops", api.getGitops)
mux.HandleFunc("POST /api/gitops/refresh", api.refreshGitops)
mux.Handle("/", static)

// getGitops serves what the deploy show command last said about the GitOps
// repository, running it on the first request and reusing that until a POST.
func (s *apiServer) getGitops(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.cachedGitops(r.Context(), false))
}

// refreshGitops re-runs the command and returns the fresh result, picking up
// a deployment someone just landed from another terminal.
func (s *apiServer) refreshGitops(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.cachedGitops(r.Context(), true))
}

// cachedGitops returns the repository declaration — computed on first use or
// when force is set, reused otherwise.
//
// The mutex is held across the provider call for the same reason as
// cachedDeployState: the command takes an exclusive lock on the shared GitOps
// checkout, so two requests running it at once would have one of them fail on
// the other's lock. Serialising turns that failure into a wait, and shares
// one run across concurrent requests.
func (s *apiServer) cachedGitops(ctx context.Context, force bool) gitopsState {
	s.gitopsMu.Lock()
	defer s.gitopsMu.Unlock()
	if s.gitopsLoaded && !force {
		return s.gitops
	}

	// Bounded for the checkout lock rather than for the browser, under the
	// same reasoning as deployStateTimeout.
	ctx, cancel := context.WithTimeout(ctx, deployStateTimeout)
	defer cancel()
	s.gitops, s.gitopsLoaded = s.gitopsProv(ctx), true
	return s.gitops
}

// warmGitops triggers the repository read in the background when the cache is
// cold. The first GET would otherwise block on a checkout refresh; an early
// endpoint asks this instead, so the GitOps view opens warm. Only one warm-up
// runs at a time — cachedGitops serialises on gitopsMu, and warming guards
// against stacking requests behind it.
func (s *apiServer) warmGitops() {
	s.gitopsMu.Lock()
	if s.gitopsLoaded || s.gitopsWarming {
		s.gitopsMu.Unlock()
		return
	}
	s.gitopsWarming = true
	s.gitopsMu.Unlock()

	go func() {
		defer func() {
			s.gitopsMu.Lock()
			s.gitopsWarming = false
			s.gitopsMu.Unlock()
		}()
		// The requests that triggered this are already answered; the
		// computation is for the GitOps view.
		_ = s.cachedGitops(context.Background(), false)
	}()
}

