 	}
 	return out
 }

+// splitYAMLDocuments breaks a manifest stream on "---" separator lines.
+//
+// Splitting by hand rather than decoding a stream with yaml.Decoder, because
+// the scanner's contract is to skip a malformed document and carry on — and
+// after a decode error the stream decoder cannot reliably find the next
+// document boundary. A line split can: each chunk parses or it does not, and
+// the rest of the file is unaffected either way.
+func splitYAMLDocuments(data []byte) [][]byte {
+	var docs [][]byte
+	start := 0
+	lines := strings.SplitAfter(string(data), "\n")
+	offset := 0
+	for _, line := range lines {
+		if strings.TrimRight(line, " \t\r\n") == "---" {
+			if doc := data[start:offset]; len(strings.TrimSpace(string(doc))) > 0 {
+				docs = append(docs, doc)
+			}
+			start = offset + len(line)
+		}
+		offset += len(line)
+	}
+	if doc := data[start:]; len(strings.TrimSpace(string(doc))) > 0 {
+		docs = append(docs, doc)
+	}
+	return docs
+}
