// GitOps repository declaration (internal/deploy ShowResult). The server
// obtains the record by running the `deploy show` command with a JSON writer
// and passing its result through unchanged, so everything below is that
// command's own output: what the repository declares, read from git only.

export interface RepositoryInfo {
  url: string
  /** Full HEAD sha of the refreshed checkout. */
  revision: string
}

export interface ArgocdInfo {
  server: string
  appNamespace: string
}

/** deploy.yaml's platform declaration. Absent means "not declared", which is
 *  not the same claim as an empty string. */
export interface PlatformInfo {
  provider?: string
  pubsub?: string
  secretStore?: string
}

/** One environment's declared policy. The list arrives in promotion order:
 *  the last entry is the furthest downstream. */
export interface EnvironmentInfo {
  name: string
  sync: 'auto' | 'manual' | string
  promotesFrom?: string[]
  requireSourceHealthy?: boolean
  /** Carried verbatim from deploy.yaml; semantics not yet defined. */
  scratch?: boolean
}

/** One secret-bearing resource and where it was seen. */
export interface SecretRef {
  kind: 'Secret' | 'ExternalSecret' | 'SealedSecret' | 'secretGenerator' | string
  name: string
  /** Owning coordinate ("domain/system/component"), flattened for list views. */
  component: string
  /** Repository-relative file; absent for a secretGenerator. */
  file?: string
}

export interface ComponentInfo {
  name: string
  kind: 'service' | 'shared' | string
  images?: string[]
  /** The component.yaml declared list, verbatim — NOT promotion order. */
  environments: string[]
  secrets?: SecretRef[]
  /** An unreadable or invalid component.yaml; the rest of the tree still lists. */
  error?: string
}

export interface SystemInfo {
  domain: string
  system: string
  components: ComponentInfo[]
}

export interface ShowResult {
  repository: RepositoryInfo
  registry: string
  argocd: ArgocdInfo
  platform: PlatformInfo
  /** In promotion order. */
  environments: EnvironmentInfo[]
  systems: SystemInfo[]
}

/** The /api/gitops payload: what the deploy show command said about the
 *  GitOps repository, or why it could not say anything. */
export interface GitopsState {
  show?: ShowResult
  /** The command's message, verbatim — an unconfigured GitOps repository, a
   *  checkout another deploy is holding, a missing deploy.yaml. None of these
   *  is a statement that nothing is declared; only `show` says that. */
  error?: string
  /** What the command wrote to stderr: which repository it refreshed, and any
   *  manifest the secret scanner skipped. Provenance, not failure. */
  diagnostics?: string[]
  /** RFC 3339 — when the command ran. */
  readAt: string
}

/** The /api/deploy/{path} payload: what the deploy status command said about one
 *  integration, or why it could not say anything. */

  /** What the GitOps repository declares, read once and reused by the server. */
  gitops: () => getJSON<GitopsState>('/api/gitops'),
  /** Re-run `deploy show` and return the fresh result — how you pick up a
   *  deployment just landed from another terminal. */
  refreshGitops: () =>
    requestJSON<GitopsState>('/api/gitops/refresh', { method: 'POST' }),
  health: () => getJSON<Health>('/api/health'),
}

