import { useCallback, useEffect, useState } from 'react'
import { api, type GitopsState, type SecretRef } from '../api'

// GitopsView renders what the GitOps repository declares — environments in
// promotion order, the systems and components onboarded, and the
// secret-bearing resources — fed only by /api/gitops. Every fact comes from
// the `deploy show` command's own result; nothing is re-derived here.

export function GitopsView() {
  const [state, setState] = useState<GitopsState | null>(null)
  const [fetchError, setFetchError] = useState<string | null>(null)
  const [refreshing, setRefreshing] = useState(false)

  useEffect(() => {
    api
      .gitops()
      .then(setState)
      .catch((e: unknown) => setFetchError(e instanceof Error ? e.message : String(e)))
  }, [])

  const refresh = useCallback(() => {
    setRefreshing(true)
    api
      .refreshGitops()
      .then(setState)
      .catch((e: unknown) => setFetchError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRefreshing(false))
  }, [])

  if (fetchError) {
    return <div className="banner error">{fetchError}</div>
  }
  if (!state) {
    return <p className="empty">Loading… (refreshing the GitOps checkout on first read)</p>
  }

  const show = state.show
  return (
    <div className="gitops-view">
      <div className="gitops-toolbar">
        <button
          type="button"
          className="flow-refresh"
          onClick={refresh}
          disabled={refreshing}
          title="Re-run deploy show against a refreshed checkout"
        >
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </button>
        <span className="gitops-readat" title="when the command ran">
          read {new Date(state.readAt).toLocaleString()}
        </span>
      </div>

      {state.error ? (
        // The command's own message, rendered distinctly from "nothing
        // declared": it says why the repository could not be described.
        <div className="banner error">{state.error}</div>
      ) : show ? (
        <>
          <section className="gitops-section">
            <h2 className="gitops-heading">Repository</h2>
            <dl className="gitops-facts">
              <dt>url</dt>
              <dd>
                {show.repository.url}
                {show.repository.revision && (
                  <span className="gitops-rev"> @ {show.repository.revision.slice(0, 7)}</span>
                )}
              </dd>
              <dt>registry</dt>
              <dd>{show.registry}</dd>
              <dt>argocd</dt>
              <dd>
                {show.argocd.server}
                {show.argocd.appNamespace && (
                  <span className="gitops-muted"> (apps in {show.argocd.appNamespace})</span>
                )}
              </dd>
              {(show.platform.provider || show.platform.pubsub || show.platform.secretStore) && (
                <>
                  <dt>platform</dt>
                  <dd>
                    {[
                      show.platform.provider && `provider ${show.platform.provider}`,
                      show.platform.pubsub && `pubsub ${show.platform.pubsub}`,
                      show.platform.secretStore && `secrets ${show.platform.secretStore}`,
                    ]
                      .filter(Boolean)
                      .join(', ')}
                  </dd>
                </>
              )}
            </dl>
          </section>

          <section className="gitops-section">
            <h2 className="gitops-heading">Environments</h2>
            <div className="gitops-pipeline">
              {show.environments.map((env, i) => (
                <div className="gitops-pipeline-step" key={env.name}>
                  {i > 0 && (
                    <span className="gitops-pipeline-arrow" aria-hidden>
                      →
                    </span>
                  )}
                  <div className="gitops-env">
                    <span className="gitops-env-name">{env.name}</span>
                    <span className={`gitops-badge${env.sync === 'manual' ? ' manual' : ''}`}>
                      {env.sync}
                    </span>
                    {env.promotesFrom?.length ? (
                      <span className="gitops-muted">from {env.promotesFrom.join(', ')}</span>
                    ) : null}
                    {env.requireSourceHealthy && (
                      <span className="gitops-badge gate">source healthy</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="gitops-section">
            <h2 className="gitops-heading">Systems</h2>
            {show.systems.length === 0 ? (
              <p className="gitops-muted">none onboarded</p>
            ) : (
              show.systems.map((sys) => (
                <div className="gitops-system" key={`${sys.domain}/${sys.system}`}>
                  <h3 className="gitops-system-name">
                    {sys.domain} / {sys.system}
                  </h3>
                  <table className="deploy-table gitops-components">
                    <thead>
                      <tr>
                        <th>Component</th>
                        <th>Kind</th>
                        <th>Environments</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sys.components.map((comp) =>
                        comp.error ? (
                          <tr className="not-onboarded" key={comp.name}>
                            <th>{comp.name}</th>
                            <td colSpan={2}>error: {comp.error}</td>
                          </tr>
                        ) : (
                          <tr key={comp.name}>
                            <th>{comp.name}</th>
                            <td>
                              <span className={`gitops-badge${comp.kind === 'shared' ? ' shared' : ''}`}>
                                {comp.kind}
                              </span>
                            </td>
                            <td>{comp.environments.join(', ')}</td>
                          </tr>
                        ),
                      )}
                    </tbody>
                  </table>
                </div>
              ))
            )}
          </section>

          <SecretsSection show={show} />
        </>
      ) : null}

      {state.diagnostics?.length ? (
        <details className="gitops-diagnostics">
          <summary>diagnostics</summary>
          {state.diagnostics.map((d) => (
            <div key={d}>{d}</div>
          ))}
        </details>
      ) : null}
    </div>
  )
}

// SecretsSection lists every secret-bearing resource, grouped by the owning
// component. SecretRef.Component is what makes this flat list possible
// without walking the systems tree again.
function SecretsSection({ show }: { show: NonNullable<GitopsState['show']> }) {
  const secrets: SecretRef[] = show.systems.flatMap((s) =>
    s.components.flatMap((c) => c.secrets ?? []),
  )

  return (
    <section className="gitops-section">
      <h2 className="gitops-heading">Secrets</h2>
      {show.platform.secretStore && (
        <p className="gitops-muted gitops-store">store {show.platform.secretStore}</p>
      )}
      {secrets.length === 0 ? (
        <p className="gitops-muted">none declared</p>
      ) : (
        <table className="deploy-table gitops-components">
          <thead>
            <tr>
              <th>Component</th>
              <th>Kind</th>
              <th>Name</th>
              <th>File</th>
            </tr>
          </thead>
          <tbody>
            {secrets.map((s, i) => (
              <tr key={`${s.component}/${s.kind}/${s.name}/${i}`}>
                <th>{s.component}</th>
                <td>
                  <span className="gitops-badge secret">{s.kind}</span>
                </td>
                <td>{s.name}</td>
                <td>{s.file ?? '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  )
}

